test('create retries are durable across flag rollback, mismatched intent rejected, and admin inventory is shared', async () => {
    const body = make(); const [a, b] = await Promise.all([createAdminImport(actor.toHexString(), body), createAdminImport(actor.toHexString(), body)]); assert.equal(a.item.id, b.item.id);
    delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
    assert.equal((await createAdminImport(actor.toHexString(), body)).receipt!.revision, 1);
    await assert.rejects(create(), errorCode('ADMIN_IMPORTS_DISABLED'));
    await assert.rejects(createAdminImport(actor.toHexString(), { ...body, manifest: { ...body.manifest, rootLabel: 'different' } }), errorCode('ADMIN_IMPORT_OPERATION_CONFLICT'));
    assert.equal((await getAdminImport(other.toHexString(), a.item.id)).item.startedByMe, false);
    await assert.rejects(getAdminImport(ordinary.toHexString(), a.item.id), errorCode('ADMIN_IMPORT_ADMIN_REQUIRED'));
    assert.equal(await getDb()!.collection('adminAlbumImports').countDocuments(), 1);
});
test('manual draft revision races have one winner and replay survives later edits', async () => {
    const first = await create(), draft = first.item.draft; draft.album.title = 'First'; const body = { ...mutation(1), draft };
    const results = await Promise.allSettled([editAdminImport(actor.toHexString(), first.item.id, body), editAdminImport(other.toHexString(), first.item.id, { ...mutation(1), draft: { ...draft, album: { ...draft.album, title: 'Other' } } })]);
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 1); assert.equal(results.filter(r => r.status === 'rejected').length, 1);
    const current = await getAdminImport(actor.toHexString(), first.item.id); assert.equal(current.item.revision, 2);
    const winning = results[0].status === 'fulfilled'; if (winning) assert.equal((await editAdminImport(actor.toHexString(), first.item.id, body)).receipt!.revision, 2);
});
